{
  "name": "opencode-context-guard",
  "version": "0.1.0",
  "description": "Warns, once per threshold, how large an OpenCode session's context has grown and what one more turn on that model costs.",
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "src",
    "index.ts",
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context",
    "tokens",
    "cost"
  ],
  "scripts": {
    "test": "node --test test/"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/pierangeloc/opencode-context-guard.git"
  },
  "homepage": "https://github.com/pierangeloc/opencode-context-guard#readme",
  "bugs": {
    "url": "https://github.com/pierangeloc/opencode-context-guard/issues"
  }
}
